package com.copiosa.domain.conjugation

/**
 * One language's bundled verb lexicon: its most frequent verbs, with every cell that deviates from
 * [Conjugator]. Generated by `tools/build_conjugations.py`; reach one through
 * [ConjugationSpec.lexicon] rather than constructing it.
 *
 * An empty lexicon is a supported state — it is what makes `LanguageFeature.CONJUGATION` report
 * unsatisfied for a language whose data hasn't been generated yet, instead of offering a drill with
 * nothing in it.
 */
class VerbLexicon(val verbs: List<VerbEntry>) {

    private val byInfinitive: Map<String, VerbEntry> by lazy { verbs.associateBy { it.infinitive } }

    private val byClass: Map<IrregularityClass, List<VerbEntry>> by lazy {
        buildMap<IrregularityClass, MutableList<VerbEntry>> {
            verbs.forEach { verb -> verb.classes.forEach { getOrPut(it) { mutableListOf() } += verb } }
        }
    }

    fun byInfinitive(infinitive: String): VerbEntry? = byInfinitive[infinitive]

    /** Every verb exhibiting [cls] somewhere in its paradigms, most frequent first. */
    fun verbsInClass(cls: IrregularityClass): List<VerbEntry> = byClass[cls].orEmpty()

    /** Classes with enough members to build a `generalize` card from — see [MIN_GENERALIZE_VERBS]. */
    val generalizableClasses: List<IrregularityClass> by lazy {
        IrregularityClass.entries.filter { verbsInClass(it).size >= MIN_GENERALIZE_VERBS }
    }

    companion object {
        /**
         * A generalize card shows a pattern by example and then asks for a verb the learner has never
         * drilled, so the class needs exemplars to show *and* at least one unseen verb to ask about.
         */
        const val MIN_GENERALIZE_VERBS = 3
    }
}
